#[cfg(test)]
mod tests {
    use super::*;

    fn norm(combos: Vec<Vec<u32>>) -> Vec<Vec<u32>> {
        let mut out: Vec<Vec<u32>> = combos
            .into_iter()
            .map(|mut c| {
                c.sort();
                c
            })
            .collect();
        out.sort();
        out
    }

    #[test]
    fn basic() {
        assert_eq!(
            norm(sum_combinations(&[2, 3, 5], 8)),
            vec![vec![2, 2, 2, 2], vec![2, 3, 3], vec![3, 5]]
        );
    }

    #[test]
    fn none_possible() {
        assert!(sum_combinations(&[4, 6], 3).is_empty());
    }

    #[test]
    fn single_candidate() {
        assert_eq!(norm(sum_combinations(&[3], 9)), vec![vec![3, 3, 3]]);
    }

    #[test]
    fn no_duplicate_orderings() {
        let out = sum_combinations(&[2, 3, 6, 7], 7);
        assert_eq!(out.len(), 2);
        assert_eq!(norm(out), vec![vec![2, 2, 3], vec![7]]);
    }

    #[test]
    fn count() {
        let out = sum_combinations(&[1, 2, 5], 10);
        assert_eq!(out.len(), 10);
        assert!(out.iter().all(|c| c.iter().sum::<u32>() == 10));
        let n = out.len();
        let mut d = norm(out);
        d.dedup();
        assert_eq!(d.len(), n);
    }
}
